import {
  Column,
  CreateDateColumn,
  Entity,
  PrimaryGeneratedColumn,
  UpdateDateColumn,
} from 'typeorm';

// WHY THIS FILE EXISTS
// An "entity" is a class that describes one database table. TypeORM reads it
// to generate migrations and to load/save rows as objects. This one is the
// `users` table: the account itself (identity only, no game stats).
// Column names in the database are snake_case; in code they are camelCase,
// connected by the `name` option.
@Entity('users')
export class User {
  // uuid generated by the database, not guessable like 1, 2, 3...
  @PrimaryGeneratedColumn('uuid')
  id: string;

  // Login identifier. Unique. The service lowercases it before saving, so
  // "A@x.com" and "a@x.com" cannot be two accounts.
  @Column({ type: 'text', unique: true })
  email: string;

  // Public name shown in matches and on the leaderboard. Unique.
  @Column({ name: 'display_name', type: 'text', unique: true })
  displayName: string;

  // null for the computer opponents (bots): no password, so nobody can log in as them.
  @Column({ name: 'password_hash', type: 'text', nullable: true })
  passwordHash: string | null;

  @Column({ name: 'avatar_url', type: 'text', nullable: true })
  avatarUrl: string | null;

  // Interface language: en, fr or ar (matches the frontend's i18n).
  @Column({ type: 'text', default: 'en' })
  locale: string;

  // A computer opponent (AI_Easy, AI_Medium, AI_Hard), not a person. It has no
  // password, so nobody can log in as it; the server plays its moves.
  @Column({ name: 'is_bot', type: 'boolean', default: false })
  isBot: boolean;

  // The last time this user did anything while logged in. This is how
  // "online" works before WebSockets exist: seen in the last minute = online.
  // The session guard refreshes it (at most once every 30 seconds).
  // null: never seen since this column exists.
  @Column({ name: 'last_seen_at', type: 'timestamptz', nullable: true })
  lastSeenAt: Date | null;

  // When the user clicked the link sent to their email. null: not verified.
  @Column({ name: 'email_verified_at', type: 'timestamptz', nullable: true })
  emailVerifiedAt: Date | null;

  // SHA-256 of the 6-digit code emailed to the user (never the code itself),
  // when it stops working, and how many wrong guesses it has had.
  // null once used or never issued.
  @Column({ name: 'email_verify_hash', type: 'text', nullable: true })
  emailVerifyHash: string | null;

  @Column({ name: 'email_verify_expires_at', type: 'timestamptz', nullable: true })
  emailVerifyExpiresAt: Date | null;

  @Column({ name: 'email_verify_attempts', type: 'int', default: 0 })
  emailVerifyAttempts: number;

  // Forgot password: same idea as the email verification code above.
  @Column({ name: 'password_reset_hash', type: 'text', nullable: true })
  passwordResetHash: string | null;

  @Column({ name: 'password_reset_expires_at', type: 'timestamptz', nullable: true })
  passwordResetExpiresAt: Date | null;

  @Column({ name: 'password_reset_attempts', type: 'int', default: 0 })
  passwordResetAttempts: number;

  // Filled by the database when the row is inserted.
  @CreateDateColumn({ name: 'created_at', type: 'timestamptz' })
  createdAt: Date;

  // Refreshed automatically on every update.
  @UpdateDateColumn({ name: 'updated_at', type: 'timestamptz' })
  updatedAt: Date;
}
